export const SMALL_TALK={
 raina:['雨音发来一张入口截得太近的图片，连世界名字都没截到。“啊……不是让你猜。等我再截一张。”第二张里，她给路边一只很小的猫画了圈。','你问雨音最近收藏了什么。她先说没什么，又慢慢翻出三张完全不同的雨天地图：“这个雨棚，声音是不一样的。”','雨音开麦前有一小段空白。你正要接话，她抢着说：“我今天想先讲。”讲的是一条走错以后反而喜欢上的小路。','雨音问你有没有把一张地图收藏两次。你说可能有，她把列表往下翻了很久，小声说：“我刚刚发现，我存了四次。”'],
 ash:['阿澈宣布今晚的新手教学是怎样给自己放假。你问教材在哪，他把欢迎牌翻过来：“本课采用无教材式教学。”说完又想起还没给自己选想玩的地方。','阿澈讲起一个自己没解开的机关，连着列了三种离谱答案。你才说出第四种，他就认真拿小本子记：“这个也很有研究价值。”','你问阿澈今天带了几次新人。他掰着手指数到一半，忽然笑了：“等一下，怎么又成工作汇报了？你今天看到什么好玩的？”','阿澈把一句欢迎词念反了，自己先笑得接不下去。他说以前会立刻重来，这回决定让你保留一次吐槽权。'],
 mika:['小满想给一张普通的路牌截图起标题，列了五个，又嫌第五个太认真。“要不就叫路牌？可是它明明有一点可爱。”','小满翻出一页歪字，问你猜哪行是后来补的。你全猜错了，她开心了两秒，又发现自己其实也记反了。','小满发来一句很短的近况，后面跟了三个撤回的草稿说明。“不是大事，我只是想说今天吃到的那个真的很好吃。”','你问小满相册整理完没有。她翻了很久，最后给你看一张手挡住镜头的图：“这张特别失败，但我舍不得删。”'],
 rei:['零点说自己今天只修了一个问题，随即补充：“引入两个新问题，净收益负一。”他没有打开工程，只把最离谱的一行报错讲给你听。','你们交换窗外的天气。零点看了一眼时间，说自己的太阳比你先下班，随后认真想了想这个比喻是不是写反了。','零点发来三行极短的近况，第四行突然很长。你指出来，他停了一会儿：“那行不是说明，是吐槽。”','零点发现一盏不怎么精致、却刚好让他喜欢的灯。他试着解释原理，讲到一半笑了：“算了，这次先允许我只说好看。”'],
 lin:['凛给你哼一段歌，最后两个音忘了，干脆自己编。你听出来了，她一点不慌：“现场限定版，懂不懂。”','你问凛今天跳舞了吗。她把耳机往下一拉：“跳了半首，剩下半首拿来坐着听。效果意外地好。”','凛给一首特别安静的歌起了个很吵的名字，问你要不要猜。你猜错以后，她也承认这个标题可能只有自己看得懂。','凛说自己今天不负责带气氛，结果讲到一个小笑话又忍不住站起来比划。她坐回去时补了一句：“这不算加班，我自己想笑。”'],
 yuki:['弥生说今天只改一点，随即拿出一张画了很多箭头的草图。你看着她，她也看着草图：“……我好像对一点有什么误会。”','弥生给你讲一段纸鸟摔下来的预览，说到最后自己先笑。她这次没有请求你立刻看工程，只想确认那一下是不是很像饺子。','你问弥生有没有完成新东西。她说没有，又补了一句：“但今天知道了两种不行的做法。”语气听起来不像在给谁道歉。','弥生盯着一个细节解释了很久，突然担心自己讲太多。你问下一步会怎样，她眼睛一下亮了，又拿起刚刚放下的笔。'],
};
const REPLIES={
 raina:[['雨音读完你的回信，先回了一个很小的表情，又补了一句：“那你那边，今天是什么声音？”','她把那段同时在线的想法记下，认真说现在还没有确认时间。说完却没有像以前那样把整句话撤回。'],['雨音这次先站起来：“那我走到下个转角。”回到椅子旁时，她没有为接下来想独处道歉。','“那……再聊一小会儿。”雨音也说出自己什么时候想停，这次不是等你猜她有没有累。'],['雨音没有马上笑着说没关系。她点头，把那份每天报平安的旧约定划掉了。','她听完你的不安，先想了想：“我可以偶尔先留一句。但不是每天。”这次回答没有被扩成更多保证。']],
 ash:[['阿澈把“临时队长”那一栏也删了。“行，咱俩谁先走错谁先讲。”他显然很期待这条规则。','两段收藏都保留着，阿澈这次没抢着把你的那段也备课。'],['阿澈先问是什么游戏，听完才答应：“这个我是真想玩，不是客套。”','他第一次把最近想玩的事讲得比迎新安排还长，讲完自己都有点不好意思。'],['阿澈松了口气：“我还以为缺席一次，欢迎牌就得跟我断交。”笑完以后，他认真听见你撤回了那份期待。','你们把能分担的事写清。阿澈没有再用自己多做一点把这次讨论糊过去。']],
 mika:[['小满在日记旁画了一个空方框：“等双方真确定了，我再打钩。”她没有先写已经赴约。','她有一点失落，还是把那格空着。后来翻开别页时，也没再把所有日子都留给一个改天。'],['小满先问什么算短，随后认真划掉了自己原本想塞进去的三个节目。','她挑了一件最近的小事讲给你听，又追问你的那件。相处没有靠新承诺才能继续。'],['小满没有要你再保证一次：“那就先从这次真的能做到的开始。”','她把日记合好，讲了那次真正等着时的感受。这晚没有立刻写一个开心结尾。']],
 rei:[['零点把工程关掉：“先运行聊天模块。”他讲完才发现自己又在用工程词，笑着换了一种说法。','两个最想讲的片段都说完了。零点看了一眼结束提醒，没再顺手开一个任务。'],['文件分成两份，各自署名。零点认真写了区别，没把另一份叫作错误版本。','小目标被划得很小，剩下的代码仍各自保存。合作这次没有要求偏好全部一致。'],['零点先把你迁过去的几个时段划回去，没有顺势多要一个空位。','他听完舍不得，也说自己会想多留一会儿。提醒响时，两个人还是按刚刚讲好的时间停下。']],
 lin:[['凛哼到一半忘了词，自己先笑：“你看，不营业的时候就是这个水平。”她没有重新录一遍。','话题拐到她今天最普通的一件小事，她讲得比你想的还起劲。'],['凛认真听了你的不同感受，嘴上先吐槽一句，后来又问你具体是哪一秒。','播放器没有打开。凛选了一段自己也没走过的路，今晚并不需要再证明她适合安静还是热闹。'],['凛坐下时还带着一点气，过了一会儿才说起那晚重新开音乐有多累。','她点头让你先走，没用玩笑把独处的要求收回来。你自己的失落也没有因此被说成不许存在。']],
 yuki:[['弥生顺着线索写了一个很小的实验，没在这一晚宣布问题已经修好。','“这个你也觉得算判断吗？”她又翻了一遍记录，这次没有只指着最终成品。'],['那只笨鸟单独保存成番外。弥生本来想再修一处，后来真的把窗口关了。','短循环的范围被写清，没完成的高处动作仍留在下一版清单上。'],['弥生先问那件事具体是什么，听完才慢慢把默认模型的手放下来。','她没有再换回漂亮模型来替自己解围，而是把之前没说完的那个问题讲完了。']],
};
const CHANGE={raina:{pause:'“我今天真的写不下去。不是等谁来哄一下就能写的那种。”',stop:'“先不写了。那张椅子，我还是喜欢的。”',retry:'“我想再试一页。只有一页。”',scope:'“整条路太长了。我先画那把椅子，可以吗……算了，我是想这样画。”'},ash:{pause:'“本队长宣布暂停营业。不是客套，我今天也想自己歇会儿。”',stop:'“这趟先没通关，错误答案倒是够开一册了。”',retry:'“人齐没齐？没齐也别硬凑，我们先试能试的这一段。”',scope:'“砍一半。剩下那一半也别假装已经玩完。”'},mika:{pause:'“这一页先夹起来。我不想为了填满它，又把谁没答应的话写进去。”',stop:'“这回真的没做完。可是已经写下的那两行，我还想留着。”',retry:'“我又想试一下。这次只带一页纸！”',scope:'“我把封面先收起来。只有这一页，也得先把它写好。”'},rei:{pause:'“当前余力不足，先停。这个不是报错，是决定。”',stop:'“先归档，标未完成。别给我自动改成发布版。”',retry:'“重新排过了。只接下一步，不接整个通宵。”',scope:'“删的是范围，不是记录。限制写清楚再开门。”'},lin:{pause:'“今晚不排练。对，真的不排，你别给我数拍子。”',stop:'“先停在这儿。我还喜欢那一秒，但整首今天不做了。”',retry:'“我又想听一遍。先说好，这回不临时加返场。”',scope:'“就留这个拍点。别嫌短，短的也得真跳过才算。”'},yuki:{pause:'“先别开工程，我怕一开又说只改一点。”',stop:'“这版没飞完。别替我配一个成功落地的结尾。”',retry:'“我想了个小一点的实验……这次真的小。”',scope:'“目的地先放低。不是说飞高不好，是我想先看它真的落一次。”'}};
export function arcReply(npc,root,index){return REPLIES[npc]?.[root]?.[index]||'';}
